11	\midrule
12	0 & 7.4\% & [$-39.4$, $82.5$] \\
13	1 & 14.8\% & [$-28.6$, $89.6$] \\
14	5 & 35.4\% & [$-1.8$, $92.7$] \\
15	10 & 50.4\% & [$18.5$, $93.3$] \\
16	25 & 70.7\% & [$48.0$, $96.3$] \\
17	50 & 82.6\% & [$67.2$, $98.2$] \\
18	100\textsuperscript{*} & 90.4\% & [$81.3$, $99.1$] \\
19	200 & 94.9\% & [$89.9$, $99.5$] \\
20	500 & 97.9\% & [$95.7$, $99.8$] \\
21	\bottomrule
